import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.sql.*;

public class ManageBookingsFrame extends JFrame {
    private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Student","Equipment","Qty","Booked","Return","Status"},0){public boolean isCellEditable(int r,int c){return false;}};
    private final JTable table=new JTable(model);
    public ManageBookingsFrame(){setTitle("Manage Bookings");setSize(850,450);setLocationRelativeTo(null);JPanel p=new JPanel();for(String x:new String[]{"Approve","Reject","Mark Returned","Refresh"}){JButton b=new JButton(x);p.add(b);if(x.equals("Approve"))b.addActionListener(e->approve());if(x.equals("Reject"))b.addActionListener(e->simple("Rejected"));if(x.equals("Mark Returned"))b.addActionListener(e->returned());if(x.equals("Refresh"))b.addActionListener(e->load());}add(new JScrollPane(table),BorderLayout.CENTER);add(p,BorderLayout.SOUTH);load();}
    private void load(){model.setRowCount(0);String s="SELECT b.booking_id,u.name,e.equipment_name,b.quantity,b.booking_date,b.return_date,b.status FROM bookings b JOIN users u ON b.user_id=u.user_id JOIN equipment e ON b.equipment_id=e.equipment_id ORDER BY b.booking_id DESC";try(Connection c=DBConnection.getConnection();Statement st=c.createStatement();ResultSet r=st.executeQuery(s)){while(r.next())model.addRow(new Object[]{r.getInt(1),r.getString(2),r.getString(3),r.getInt(4),r.getDate(5),r.getDate(6),r.getString(7)});}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage());}}
    private int selected(){int r=table.getSelectedRow();return r<0?-1:(int)model.getValueAt(r,0);}
    private void approve(){int id=selected();if(id<0)return;try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{PreparedStatement p=c.prepareStatement("SELECT b.quantity,b.status,e.equipment_id,e.available_quantity FROM bookings b JOIN equipment e ON b.equipment_id=e.equipment_id WHERE b.booking_id=? FOR UPDATE");p.setInt(1,id);ResultSet r=p.executeQuery();if(!r.next()||!"Pending".equals(r.getString("status")))throw new Exception("Booking is not pending");int q=r.getInt("quantity"),avail=r.getInt("available_quantity"),eid=r.getInt("equipment_id");if(q>avail)throw new Exception("Not enough equipment available");p=c.prepareStatement("UPDATE equipment SET available_quantity=available_quantity-?, status=IF(available_quantity-? > 0,'Available','Unavailable') WHERE equipment_id=?");p.setInt(1,q);p.setInt(2,q);p.setInt(3,eid);p.executeUpdate();p=c.prepareStatement("UPDATE bookings SET status='Approved' WHERE booking_id=?");p.setInt(1,id);p.executeUpdate();c.commit();}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}load();}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage());}}
    private void simple(String status){int id=selected();if(id<0)return;try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE bookings SET status=? WHERE booking_id=? AND status='Pending'")){p.setString(1,status);p.setInt(2,id);if(p.executeUpdate()==0)JOptionPane.showMessageDialog(this,"Only pending bookings can be changed");load();}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage());}}
    private void returned(){int id=selected();if(id<0)return;try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{PreparedStatement p=c.prepareStatement("SELECT equipment_id,quantity,status FROM bookings WHERE booking_id=? FOR UPDATE");p.setInt(1,id);ResultSet r=p.executeQuery();if(!r.next()||!"Approved".equals(r.getString("status")))throw new Exception("Only approved bookings can be returned");int eid=r.getInt(1),q=r.getInt(2);p=c.prepareStatement("UPDATE equipment SET available_quantity=available_quantity+?,status='Available' WHERE equipment_id=?");p.setInt(1,q);p.setInt(2,eid);p.executeUpdate();p=c.prepareStatement("UPDATE bookings SET status='Returned' WHERE booking_id=?");p.setInt(1,id);p.executeUpdate();c.commit();}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}load();}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage());}}
}
